/** App language is an explicit device preference; Korean is the first-run default. */
export const APP_LANGUAGES=[{id:'ko',name:'한국어',locale:'ko-KR'},{id:'en',name:'English',locale:'en-US'},{id:'ja',name:'日本語',locale:'ja-JP'},{id:'zh-CN',name:'简体中文',locale:'zh-CN'},{id:'es',name:'Español',locale:'es-ES'},{id:'fr',name:'Français',locale:'fr-FR'},{id:'de',name:'Deutsch',locale:'de-DE'}] as const;
export type Lang=typeof APP_LANGUAGES[number]['id'];
export function isAppLanguage(value:unknown):value is Lang{return APP_LANGUAGES.some(x=>x.id===value);}
export const LANGUAGE_STORAGE_KEY='portmanager-lang';
export const LANGUAGE_CHANGE_EVENT='agentstoz:language';
// A failed storage write must still reach components mounted later (and voice requests).
let unsavedLanguage:Lang|undefined;
export function isAppLanguagePersisted():boolean {return unsavedLanguage===undefined;}
export function readAppLanguage():Lang {
 if(unsavedLanguage!==undefined)return unsavedLanguage;
 try{const value=globalThis.localStorage?.getItem(LANGUAGE_STORAGE_KEY);return isAppLanguage(value)?value:'ko';}catch{return 'ko';}
}
export function writeAppLanguage(lang:Lang):boolean {
 if(!isAppLanguage(lang))return false;
 let saved=false;
 try{if(globalThis.localStorage){globalThis.localStorage.setItem(LANGUAGE_STORAGE_KEY,lang);saved=true;}}catch{/* Retain this window's preference when storage is blocked or full. */}
 unsavedLanguage=saved?undefined:lang;
 if(typeof document!=='undefined')document.documentElement.lang=lang;
 if(typeof window!=='undefined')window.dispatchEvent(new CustomEvent(LANGUAGE_CHANGE_EVENT,{detail:lang}));
 return saved;
}
export function subscribeAppLanguage(onChange:()=>void):()=>void {
 if(typeof window==='undefined')return()=>{};
 const storage=(event:StorageEvent)=>{
  if(event.key!==LANGUAGE_STORAGE_KEY&&event.key!==null)return;
  // sessionStorage can use the same key; it is not an app-language preference.
  try{if(event.storageArea&&event.storageArea!==globalThis.localStorage)return;}catch{return;}
  unsavedLanguage=undefined;
  onChange();
 };
 window.addEventListener(LANGUAGE_CHANGE_EVENT,onChange);
 window.addEventListener('storage',storage);
 return()=>{window.removeEventListener(LANGUAGE_CHANGE_EVENT,onChange);window.removeEventListener('storage',storage);};
}
export function appLocale(lang:Lang):string {return APP_LANGUAGES.find(item=>item.id===lang)?.locale??'ko-KR';}
