export type TKey=keyof typeof translations['ko'];
// This assignment makes missing keys in any supported language a type error.
const catalogs:Record<Lang,Record<TKey,string>>=translations;
export function t(lang:Lang,key:TKey,values?:Record<string,string|number>):string {
 const text=catalogs[isAppLanguage(lang)?lang:'ko'][key]??catalogs.ko[key];
 return values?text.replace(/\{(\w+)\}/g,(token,name)=>Object.hasOwn(values,name)?String(values[name]):token):text;
}
export function formatProjectCount(lang:Lang,count:number):string {
 const locale=appLocale(lang);
 return t(lang,new Intl.PluralRules(locale).select(count)==='one'?'projectCountOne':'projectCountOther',{count:new Intl.NumberFormat(locale).format(count)});
}
export function formatLastRun(lang:Lang,timestamp:number|undefined,now=Date.now()):string {
 if(!timestamp||!Number.isFinite(timestamp))return t(lang,'neverRun');
 const minutes=Math.floor(Math.max(0,now-timestamp)/60000);
 if(minutes<1)return t(lang,'justNow');
 const [amount,unit]:[number,Intl.RelativeTimeFormatUnit]=minutes<60?[minutes,'minute']:minutes<1440?[Math.floor(minutes/60),'hour']:minutes<43200?[Math.floor(minutes/1440),'day']:[Math.floor(minutes/43200),'month'];
 return new Intl.RelativeTimeFormat(appLocale(lang),{numeric:'always'}).format(-amount,unit);
}

/**
 * Shape of a feature copy block, derived from its Korean source: every string leaf becomes `string`.
 * Typing a block as `Record<Lang,CopyShape<typeof ko>>` makes a missing key, an extra key or a
 * missing language a type error, the same discipline as the main `translations` catalog.
 */
export type CopyShape<T>={readonly [K in keyof T]:T[K] extends string?string:CopyShape<T[K]>};

